xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        SColors[0] := '   gb      ';
        SColors[1] := '   ro      ';
        SColors[2] := 'rw bg yw ow';
        SColors[3] := 'by rw ob yy';
        SColors[4] := '   gg      ';
        SColors[5] := '   ro      ';

        W := 0.5;

        N := 2;
        WD := 2 * W / N;
        D[0] := WD * (-N/2 + 1);
        for i := 1 to N - 2 do
            D[i] := D[i-1] + WD;

        DX :=-0.08;
        DY :=-0.20;
        DZ := 0.12;

        SColor := 'robgyw';
        function GetColor(X, Y);
        begin
            Result := -1;
            C := copy(SColors[N * SY + Y], ((N + 1) * SX + 1) + X, 1);
            i := Pos(C, SColor);
            if i > 0 then
                Result := Colors[i - 1];
        end;

